"""VersionMatcher.should_include 过滤语义测试

锁定契约（修复后）:
    - 支持 ConditionalEntry 对象（ModEntry/ExtraUrl）、dict 与字符串
    - only_version: 版本命中指定列表才包含
    - only_loader: 加载器命中指定列表才包含（列表命中其一即可）;
      声明 only_loader 但无 loader 上下文（None）时排除（保守）
    - feature: 启用条件语义——条目声明的 feature 全部被启用才包含;
      未声明 feature 的条目始终包含

背景: 历史实现对 dict 采用"全部启用则排除"反向语义, 且对对象条目
(dataclass) 的过滤因 isinstance(entry, dict) 不命中而完全失效。本套
用例锁定修复后的正确行为, 防止回归。
"""

import pytest

from modfetch.application.version_matcher import CondExpr, VersionMatcher
from modfetch.domain.config_models import ExtraUrl, ModEntry


class TestShouldIncludeObjectEntry:
    def test_mod_entry_only_version_match(self):
        """ModEntry only_version 命中 → 包含"""
        matcher = VersionMatcher()
        entry = ModEntry(id="x", only_version="1.21.1")
        assert matcher.should_include(entry, "1.21.1", [])

    def test_mod_entry_only_version_mismatch(self):
        """ModEntry only_version 未命中 → 排除"""
        matcher = VersionMatcher()
        entry = ModEntry(id="x", only_version="1.20.4")
        assert not matcher.should_include(entry, "1.21.1", [])

    def test_mod_entry_feature_enabled(self):
        """ModEntry feature 全部启用 → 包含"""
        matcher = VersionMatcher()
        entry = ModEntry(id="x", feature=["shaders", "graphics"])
        assert matcher.should_include(entry, "1.21.1", ["shaders", "graphics"])

    def test_mod_entry_feature_partial(self):
        """ModEntry feature 部分启用 → 排除"""
        matcher = VersionMatcher()
        entry = ModEntry(id="x", feature="shaders")
        assert not matcher.should_include(entry, "1.21.1", ["graphics"])

    def test_mod_entry_feature_not_enabled(self):
        """ModEntry feature 未启用 → 排除"""
        matcher = VersionMatcher()
        entry = ModEntry(id="x", feature="shaders")
        assert not matcher.should_include(entry, "1.21.1", [])

    def test_mod_entry_no_conditions_always_included(self):
        """ModEntry 无条件 → 始终包含"""
        matcher = VersionMatcher()
        entry = ModEntry(id="x")
        assert matcher.should_include(entry, "1.21.1", [])

    def test_extra_url_relative_preserved(self):
        """ExtraUrl 无条件 → 包含"""
        matcher = VersionMatcher()
        entry = ExtraUrl(url="https://example.com/x.zip")
        assert matcher.should_include(entry, "1.21.1", [])

    def test_str_entry_always_included(self):
        """字符串条目无条件 → 包含"""
        matcher = VersionMatcher()
        assert matcher.should_include("sodium", "1.21.1", [])


class TestShouldIncludeDict:
    def test_dict_feature_enabled(self):
        """dict feature 启用 → 包含"""
        matcher = VersionMatcher()
        assert matcher.should_include(
            {"id": "x", "feature": "shaders"}, "1.21.1", ["shaders"]
        )

    def test_dict_feature_not_enabled(self):
        """dict feature 未启用 → 排除"""
        matcher = VersionMatcher()
        assert not matcher.should_include(
            {"id": "x", "feature": "shaders"}, "1.21.1", []
        )


class TestOnlyLoaderGate:
    def test_loader_match_included(self):
        """only_loader 命中 → 包含"""
        matcher = VersionMatcher()
        entry = ModEntry(id="x", only_loader="fabric")
        assert matcher.should_include(entry, "1.21.1", [], "fabric")

    def test_loader_mismatch_excluded(self):
        """only_loader 未命中 → 排除"""
        matcher = VersionMatcher()
        entry = ModEntry(id="x", only_loader="fabric")
        assert not matcher.should_include(entry, "1.21.1", [], "forge")

    def test_loader_list_any_match(self):
        """only_loader 列表命中其一 → 包含"""
        matcher = VersionMatcher()
        entry = ModEntry(id="x", only_loader=["fabric", "forge"])
        assert matcher.should_include(entry, "1.21.1", [], "forge")
        assert not matcher.should_include(entry, "1.21.1", [], "neoforge")

    def test_loader_no_context_excluded(self):
        """声明 only_loader 但无 loader 上下文（None）→ 保守排除"""
        matcher = VersionMatcher()
        entry = ModEntry(id="x", only_loader="fabric")
        assert not matcher.should_include(entry, "1.21.1", [])

    def test_loader_case_insensitive(self):
        """加载器匹配大小写不敏感"""
        matcher = VersionMatcher()
        entry = ModEntry(id="x", only_loader="Fabric")
        assert matcher.should_include(entry, "1.21.1", [], "fabric")

    def test_loader_combined_with_version_and_feature(self):
        """only_loader + only_version + feature 同时满足才包含（AND）"""
        matcher = VersionMatcher()
        entry = ModEntry(
            id="x",
            only_version="1.21.1",
            only_loader="fabric",
            feature="graphics",
        )
        assert matcher.should_include(
            entry, "1.21.1", ["graphics"], "fabric"
        )
        assert not matcher.should_include(entry, "1.20.4", ["graphics"], "fabric")
        assert not matcher.should_include(entry, "1.21.1", ["graphics"], "forge")
        assert not matcher.should_include(entry, "1.21.1", [], "fabric")

    def test_dict_only_loader(self):
        """dict 条目 only_loader 同样生效"""
        matcher = VersionMatcher()
        assert matcher.should_include(
            {"id": "x", "only_loader": "forge"}, "1.21.1", [], "forge"
        )
        assert not matcher.should_include(
            {"id": "x", "only_loader": "forge"}, "1.21.1", [], "fabric"
        )

    def test_extra_url_only_loader(self):
        """ExtraUrl 同样支持 only_loader"""
        matcher = VersionMatcher()
        entry = ExtraUrl(url="https://example.com/x.zip", only_loader="fabric")
        assert matcher.should_include(entry, "1.21.1", [], "fabric")
        assert not matcher.should_include(entry, "1.21.1", [], "forge")


class TestCondExpr:
    """cond 表达式：字面量分类 / 运算符 / 优先级 / 无前缀推断 / 语法错误"""

    def test_version_literal(self):
        """v: 前缀按版本精确匹配"""
        assert CondExpr.evaluate("v:1.21.1", "1.21.1", [], "fabric")
        assert not CondExpr.evaluate("v:1.21.1", "1.20.4", [], "fabric")

    def test_loader_literal_case_insensitive(self):
        """l: 前缀按加载器匹配（大小写不敏感）"""
        assert CondExpr.evaluate("l:fabric", "1.21.1", [], "FABRIC")
        assert not CondExpr.evaluate("l:fabric", "1.21.1", [], "forge")

    def test_loader_literal_no_context_excluded(self):
        """l: 前缀无 loader 上下文 → 保守排除"""
        assert not CondExpr.evaluate("l:fabric", "1.21.1", [])

    def test_feature_literal(self):
        """f: 前缀按 feature 启用列表匹配"""
        assert CondExpr.evaluate("f:shaders", "1.21.1", ["shaders"], "fabric")
        assert not CondExpr.evaluate("f:shaders", "1.21.1", [], "fabric")

    def test_long_prefixes(self):
        """version:/loader:/feature: 长前缀等价"""
        assert CondExpr.evaluate("version:1.21.1", "1.21.1", [], "fabric")
        assert CondExpr.evaluate("loader:fabric", "1.21.1", [], "fabric")
        assert CondExpr.evaluate("feature:shaders", "1.21.1", ["shaders"], "fabric")

    def test_and_or_precedence(self):
        """&& 优先级高于 ||（a || b && c == a || (b && c)）"""
        # b && c 为假但 a 为真 → 整体为真
        assert CondExpr.evaluate(
            "v:1.21.1 || l:forge && f:shaders", "1.21.1", [], "forge"
        )
        # a 为假, b && c 为真 → 整体为真
        assert CondExpr.evaluate(
            "v:1.20.4 || l:forge && f:shaders", "1.21.1", ["shaders"], "forge"
        )
        # a 为假, b && c 为假 → 整体为假
        assert not CondExpr.evaluate(
            "v:1.20.4 || l:forge && f:shaders", "1.21.1", [], "forge"
        )

    def test_parentheses_override_precedence(self):
        """括号覆盖默认优先级"""
        assert CondExpr.evaluate(
            "(v:1.21.1 || v:1.21.7) && l:fabric", "1.21.7", [], "fabric"
        )
        assert not CondExpr.evaluate(
            "(v:1.21.1 || v:1.21.7) && l:fabric", "1.21.7", [], "forge"
        )

    def test_not_operator(self):
        """! 取反（一元，优先级最高）"""
        assert CondExpr.evaluate("!l:fabric", "1.21.1", [], "forge")
        assert not CondExpr.evaluate("!l:fabric", "1.21.1", [], "fabric")
        assert CondExpr.evaluate("!f:shaders", "1.21.1", [], "fabric")

    def test_not_binds_tighter_than_and(self):
        """!a && b 解析为 (!a) && b"""
        assert CondExpr.evaluate("!v:1.20.4 && l:fabric", "1.21.1", [], "fabric")
        assert not CondExpr.evaluate("!v:1.21.1 && l:fabric", "1.21.1", [], "fabric")

    def test_bare_literal_auto_inference(self):
        """无前缀字面量按 版本 → 加载器 → feature 顺序推断"""
        assert CondExpr.evaluate("1.21.1", "1.21.1", [], "fabric")
        assert CondExpr.evaluate("fabric", "1.21.1", [], "fabric")
        assert CondExpr.evaluate("shaders", "1.21.1", ["shaders"], "fabric")
        assert not CondExpr.evaluate("neoforge", "1.21.1", [], "fabric")

    def test_list_implicit_and(self):
        """cond 列表元素隐含 AND"""
        assert CondExpr.evaluate(
            ["v:1.21.1", "l:fabric"], "1.21.1", [], "fabric"
        )
        assert not CondExpr.evaluate(
            ["v:1.21.1", "l:forge"], "1.21.1", [], "fabric"
        )

    def test_empty_cond_false(self):
        """空字符串 / 空列表 → False（调用方回退到单独字段）"""
        assert not CondExpr.evaluate("", "1.21.1", [], "fabric")
        assert not CondExpr.evaluate([], "1.21.1", [], "fabric")

    def test_syntax_error_fail_fast(self):
        """语法错误 fail-fast 抛 ValueError（中文消息）"""
        for bad in ("v:1.21.1 &&", "a & b", "a | b", "(a", "a)", "a && &&"):
            with pytest.raises(ValueError, match="cond 表达式"):
                CondExpr.evaluate(bad, "1.21.1", [], "fabric")


class TestCondPriorityOverSeparateFields:
    """cond 声明时忽略 only_version / only_loader / feature"""

    def test_cond_wins_over_contradicting_fields(self):
        """单独字段满足但 cond 不满足 → 排除"""
        matcher = VersionMatcher()
        entry = ModEntry(
            id="x",
            cond="v:1.21.7",
            only_version="1.21.1",  # 单独字段与 cond 矛盾
            only_loader="fabric",
            feature="shaders",
        )
        assert not matcher.should_include(entry, "1.21.1", ["shaders"], "fabric")
        assert matcher.should_include(entry, "1.21.7", [], "forge")

    def test_cond_empty_falls_back_to_fields(self):
        """cond 为空字符串 → 回退到单独字段逻辑"""
        matcher = VersionMatcher()
        entry = ModEntry(id="x", cond="", only_version="1.21.1")
        assert matcher.should_include(entry, "1.21.1", [])
        assert not matcher.should_include(entry, "1.20.4", [])

    def test_dict_cond_priority(self):
        """dict 条目 cond 同样优先"""
        matcher = VersionMatcher()
        assert matcher.should_include(
            {"id": "x", "cond": "l:fabric", "only_loader": "forge"},
            "1.21.1", [], "fabric",
        )
        assert not matcher.should_include(
            {"id": "x", "cond": "l:fabric", "only_loader": "forge"},
            "1.21.1", [], "forge",
        )

    def test_extra_url_cond(self):
        """ExtraUrl cond 同样生效"""
        matcher = VersionMatcher()
        entry = ExtraUrl(
            url="https://example.com/x.zip", cond="f:shaders"
        )
        assert matcher.should_include(entry, "1.21.1", ["shaders"], "fabric")
        assert not matcher.should_include(entry, "1.21.1", [], "fabric")